// === Tab: mySketch ===
// Attractor?_13.0

let N = 10000 ; let M = 3 ; let K = 0.01 ; let V = 0.4 ; let R = 300 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ; let CX[] = new Array(M) ; let CY[] = new Array(M) ;
let L ; let I ; let II ; let KX ; let KY ; let KZ ; let KdX ; let KdY ; let NKX ; let NKY ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(600, 600) ; noSmooth() ; background(0) ; stroke(255) ; textSize(20) ;

  X[0] = 200 ; Y[0] = 0 ; Z[0] = 0 ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = X[0]+random(-1,+1) ; Y[I] = Y[0]+random(-1,+1) ; Z[I] = Z[0]+random(-1,+1) ; 
  }

  for ( I = 0 ; I < M ; I++ ){
    CX[I] = (R-20)*2/sqrt(3)*cos(2*PI*I/M)+200 ; CY[I] = (R-20)*2/sqrt(3)*sin(2*PI*I/M) ; 
  }

  KN = N ; 

}// setup()

function draw(){

  if ( KN == N ){ background(0) ; }
  line(50,300,550,300) ; line(550,300,540,290) ; line(550,300,540,310) ; text("X",560,305) ;
  line(300,50,300,550) ; line(300,50,290,60) ; line(300,50,310,60) ; text("Z",295,40) ;
  line(450,150,150,450) ; line(150,450,150,435) ; line(150,450,165,450) ; text("Y",130,470) ;

  for ( I = 0 ; I < KN ; I++ ){

     L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
     KX = L ; KY = Z[I] ; KdX = X[I]/L ; KdY = Y[I]/L ;

     for ( II = 0 ; II < M ; II++ ){
       L = sqrt(pow(KX-CX[II],2)+pow(KY-CY[II],2)) ;
       if ( L < R ){
         KdX = KdX + ((R-L)*K*(KX-CX[II])/L) ;
         KdY = KdY + ((R-L)*K*(KY-CY[II])/L) ; 
       }
     }

     L = sqrt(pow(KdX,2)+pow(KdY,2)) ;
     if ( L > 0 ){ KdX = KdX*V/L ; KdY = KdY*V/L ; }
     L = sqrt(pow(KdX,2)+pow(KdY,2)) ;
     NKX = KX + KdX ; NKY = KY + KdY ;
     NX = NKX*KdX/L ; NY = NKX*KdY/L ; NZ = NKY ;

     line(NX-(NY/2)+300,-NZ+(NY/2)+300,X[I]-(Y[I]/2)+300,-Z[I]+(Y[I]/2)+300) ;
     X[I] = NX ; Y[I] = NY ; Z[I] = NZ ;

  }// I

}// draw()

function mousePressed(){

  background(0) ;

  if ( KN != N ){ 
    KN = N ; 
    for ( I = 0 ; I < N ; I++ ){
      X[I] = X[0]+random(-1,+1) ; Y[I] = Y[0]+random(-1,+1) ; Z[I] = Z[0]+random(-1,+1) ; 
    }
  }else{ KN = 1 ; }

}// mousePressed()

